import Extensions
import FilenameMatcher
import SystemPackage

public extension Configuration {
    /// The code that SwiftPM build tool plugins generate, under `<scratch path>/plugins/outputs`: indexed for its
    /// references to the project, left out of the results by the default of `report_exclude`.
    static let buildPluginOutputsGlob = "**/plugins/outputs/**"

    /// Whether the file was generated by a build tool plugin.
    func isBuildPluginOutput(_ path: FilePath) -> Bool {
        Self.buildPluginOutputsMatcher.match(filename: path.string)
    }

    // MARK: - Private

    /// Only read once built.
    private nonisolated(unsafe) static let buildPluginOutputsMatcher = FilenameMatcher(relativePattern: buildPluginOutputsGlob, to: "/", caseSensitive: false)
}

extension Configuration {
    /// The `index_exclude` globs given, without the default ones that `exclude.index_defaults` adds.
    var givenIndexExclude: [String] {
        guard $indexExclude.isNormalizing else { return indexExclude }

        let defaults = $indexExclude.defaultValue
        return indexExclude.filter { !defaults.contains($0) }
    }
}
